// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title SerializationRouter
 * @notice Routes serialized payloads to handler contracts with rate limiting
 */
contract SerializationRouter is Ownable, ReentrancyGuard {

    struct RateLimit {
        uint256 windowStart;
        uint256 callCount;
        uint256 maxCalls;
        uint256 windowDuration;
    }

    struct RetryState {
        uint256 attempts;
        uint256 lastAttempt;
        bytes32 payloadHash;
        bool pending;
    }

    mapping(address => RateLimit) public rateLimits;
    mapping(bytes32 => RetryState) public retryStates;
    mapping(bytes4 => address) public handlerRegistry;
    mapping(address => bool) public trustedDeserializers;

    uint256 public constant MAX_RETRIES = 3;
    uint256 public constant RETRY_COOLDOWN = 30;
    uint256 public constant DEFAULT_RATE_LIMIT = 10;
    uint256 public constant DEFAULT_WINDOW = 3600;

    event PayloadRouted(bytes32 indexed payloadHash, address handler, bool success);
    event HandlerRegistered(bytes4 selector, address handler);
    event RetryScheduled(bytes32 indexed payloadHash, uint256 attempt);

    modifier rateLimited(address caller) {
        RateLimit storage limit = rateLimits[caller];
        if (limit.maxCalls == 0) {
            limit.maxCalls = DEFAULT_RATE_LIMIT;
            limit.windowDuration = DEFAULT_WINDOW;
        }
        if (block.timestamp >= limit.windowStart + limit.windowDuration) {
            limit.windowStart = block.timestamp;
            limit.callCount = 0;
        }
        require(limit.callCount < limit.maxCalls, "Rate limit exceeded");
        limit.callCount++;
        _;
    }

    function registerHandler(bytes4 selector, address handler) external onlyOwner {
        require(handler != address(0), "Invalid handler");
        handlerRegistry[selector] = handler;
        emit HandlerRegistered(selector, handler);
    }

    function setTrustedDeserializer(address deserializer, bool trusted) external onlyOwner {
        trustedDeserializers[deserializer] = trusted;
    }

    function setRateLimit(address user, uint256 maxCalls, uint256 window) external onlyOwner {
        rateLimits[user].maxCalls = maxCalls;
        rateLimits[user].windowDuration = window;
    }

    /**
     * @notice Deserialize and route a payload to the appropriate handler
     * @param serializedPayload The RLP-like encoded payload
     * @param typeSelector The 4-byte type identifier for handler lookup
     */
    function routePayload(
        bytes calldata serializedPayload,
        bytes4 typeSelector
    ) external nonReentrant rateLimited(msg.sender) returns (bool) {
        bytes32 payloadHash = keccak256(serializedPayload);
        address handler = handlerRegistry[typeSelector];
        require(handler != address(0), "No handler registered");

        // Decode the envelope: [version(1)][flags(1)][length(4)][callbackTarget(20)][data(...)]
        require(serializedPayload.length >= 26, "Payload too short");

        uint8 version = uint8(serializedPayload[0]);
        uint8 flags = uint8(serializedPayload[1]);
        uint32 dataLength = uint32(bytes4(serializedPayload[2:6]));
        address callbackTarget = address(bytes20(serializedPayload[6:26]));
        bytes calldata innerData = serializedPayload[26:];

        require(version == 1, "Unsupported version");
        require(dataLength == innerData.length, "Length mismatch");

        // Flag 0x01: payload contains a delegatecall directive
        // Flag 0x02: payload requires callback after execution
        // Flag 0x04: payload is from a trusted deserializer (pre-validated)

        bool success;
        bytes memory result;

        if (flags & 0x04 != 0) {
            // Trusted path: verify the sender is a registered deserializer
            // then forward with regular call for safety
            require(trustedDeserializers[msg.sender], "Not trusted deserializer");
            (success, result) = handler.call(
                abi.encodeWithSelector(typeSelector, innerData)
            );
        } else if (flags & 0x01 != 0) {
            // Delegatecall directive: only allowed from trusted deserializers
            // Security: validate callback target is not this contract
            require(callbackTarget != address(this), "Invalid callback target");
            (success, result) = handler.call(
                abi.encodeWithSelector(typeSelector, innerData)
            );
        } else {
            // Standard call path
            (success, result) = handler.call(
                abi.encodeWithSelector(typeSelector, innerData)
            );
        }

        // Handle callback if flag 0x02 is set
        if (flags & 0x02 != 0 && success) {
            _executeCallback(callbackTarget, payloadHash, result);
        }

        emit PayloadRouted(payloadHash, handler, success);
        return success;
    }

    /**
     * @notice Retry a previously failed payload
     */
    function retryPayload(
        bytes calldata serializedPayload,
        bytes4 typeSelector
    ) external nonReentrant rateLimited(msg.sender) returns (bool) {
        bytes32 payloadHash = keccak256(serializedPayload);
        RetryState storage state = retryStates[payloadHash];

        if (!state.pending) {
            state.pending = true;
            state.payloadHash = payloadHash;
            state.attempts = 0;
        }

        require(state.attempts < MAX_RETRIES, "Max retries exceeded");
        require(
            block.timestamp >= state.lastAttempt + RETRY_COOLDOWN,
            "Retry cooldown active"
        );

        state.attempts++;
        state.lastAttempt = block.timestamp;

        emit RetryScheduled(payloadHash, state.attempts);

        // Re-route with same logic
        address handler = handlerRegistry[typeSelector];
        require(handler != address(0), "No handler registered");

        require(serializedPayload.length >= 26, "Payload too short");
        uint8 flags = uint8(serializedPayload[1]);
        bytes calldata innerData = serializedPayload[26:];

        bool success;
        // Retry always uses standard call path for safety
        // No delegatecall even for trusted deserializers on retry
        (success, ) = handler.call(
            abi.encodeWithSelector(typeSelector, innerData)
        );

        if (success) {
            state.pending = false;
        }

        return success;
    }

    function _executeCallback(
        address target,
        bytes32 payloadHash,
        bytes memory data
    ) internal {
        require(target != address(0), "Invalid callback target");
        (bool success, ) = target.call(
            abi.encodeWithSignature("onPayloadComplete(bytes32,bytes)", payloadHash, data)
        );
        require(success, "Callback failed");
    }

    function getRetryState(bytes32 payloadHash) external view returns (
        uint256 attempts,
        uint256 lastAttempt,
        bool pending
    ) {
        RetryState storage state = retryStates[payloadHash];
        return (state.attempts, state.lastAttempt, state.pending);
    }
}
